INSERT INTO `product` (`id`, `sku`, `featuredImage`, `categoryId`, `description`, `published`, `metaTitle`, `metaDescription`, `createdAt`, `updatedAt`, `name`, `slug`, `specs`, `accessories`, `basePrice`, `minOrder`, `shortDescription`, `sheetStatus`, `sites`, `sortOrder`) VALUES ('313', 'RO.J.SP-15', NULL, NULL, '<p><strong>Lanyard RING O Jahit Stopper Punggung 1.5 cm</strong> adalah produk unggulan dari IndoLanyard yang didesain khusus untuk memberikan kesan profesional dan elegan. Dengan lebar tali 1.5 cm, produk ini memberikan kesan minimalis dan ringan saat digunakan. Menggunakan cantolan Ring O klasik yang fleksibel untuk berbagai macam casing kartu identitas. Terdapat fitur *Safety Breakaway* (Stopper Punggung) sebagai keamanan ekstra; jika tali tidak sengaja tersangkut, stopper ini akan otomatis terlepas untuk mencegah cedera pada leher. Kami menggunakan teknik penyatuan *Finishing Jahit* yang ekstra rapi dan sangat kuat, memastikan lanyard tidak mudah terurai atau rusak. </p><p>Sangat direkomendasikan untuk keperluan ID Card Karyawan, Panitia Event, Komunitas, maupun Merchandise Perusahaan. Kualitas cetak *Full Color* (Printing) kami dijamin tajam, tidak mudah luntur, dan tahan lama!</p>', '1', NULL, NULL, '2026-07-15 08:43:17.000', '2026-07-15 08:43:17.000', 'Tali Lanyard Custom Ring O Jahit Stopper Punggung 1.5 cm', 'tali-lanyard-custom-ring-o-jahit-stopper-punggung-15-cm', NULL, NULL, 'Rp 17.000', NULL, 'Lanyard RING O Jahit Stopper Punggung 1.5 cm', 'Publish', 'All', '313') ON DUPLICATE KEY UPDATE `sku` = VALUES(`sku`), `featuredImage` = VALUES(`featuredImage`), `categoryId` = VALUES(`categoryId`), `description` = VALUES(`description`), `published` = VALUES(`published`), `metaTitle` = VALUES(`metaTitle`), `metaDescription` = VALUES(`metaDescription`), `createdAt` = VALUES(`createdAt`), `updatedAt` = VALUES(`updatedAt`), `name` = VALUES(`name`), `slug` = VALUES(`slug`), `specs` = VALUES(`specs`), `accessories` = VALUES(`accessories`), `basePrice` = VALUES(`basePrice`), `minOrder` = VALUES(`minOrder`), `shortDescription` = VALUES(`shortDescription`), `sheetStatus` = VALUES(`sheetStatus`), `sites` = VALUES(`sites`), `sortOrder` = VALUES(`sortOrder`);
